import{_ as o,c as t,o as a,aj as r}from"./chunks/framework.BlveriQe.js";const p=JSON.parse('{"title":"Interface: WorkflowRun","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/WorkflowRun.md","filePath":"reference/js-bao-wss-client/api/interfaces/WorkflowRun.md"}'),d={name:"reference/js-bao-wss-client/api/interfaces/WorkflowRun.md"};function l(n,e,c,s,i,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / WorkflowRun</p><h1 id="interface-workflowrun" tabindex="-1">Interface: WorkflowRun <a class="header-anchor" href="#interface-workflowrun" aria-label="Permalink to “Interface: WorkflowRun”">​</a></h1><p>A workflow run record</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="contextdocid" tabindex="-1">contextDocId? <a class="header-anchor" href="#contextdocid" aria-label="Permalink to “contextDocId?”">​</a></h3><blockquote><p><code>optional</code> <strong>contextDocId?</strong>: <code>string</code></p></blockquote><hr><h3 id="createcalldurationms" tabindex="-1">createCallDurationMs? <a class="header-anchor" href="#createcalldurationms" aria-label="Permalink to “createCallDurationMs?”">​</a></h3><blockquote><p><code>optional</code> <strong>createCallDurationMs?</strong>: <code>number</code> | <code>null</code></p></blockquote><p>Wall-clock ms the server spent on the run-creation call itself. <code>null</code> for runs started via a path that does not record it.</p><hr><h3 id="endedat" tabindex="-1">endedAt? <a class="header-anchor" href="#endedat" aria-label="Permalink to “endedAt?”">​</a></h3><blockquote><p><code>optional</code> <strong>endedAt?</strong>: <code>string</code></p></blockquote><hr><h3 id="errormessage" tabindex="-1">errorMessage? <a class="header-anchor" href="#errormessage" aria-label="Permalink to “errorMessage?”">​</a></h3><blockquote><p><code>optional</code> <strong>errorMessage?</strong>: <code>string</code> | <code>null</code></p></blockquote><p>Error message when <code>status</code> is <code>&quot;failed&quot;</code>, <code>null</code> otherwise. Always present in run responses (the server sends <code>errorMessage || null</code>).</p><hr><h3 id="errortitle" tabindex="-1">errorTitle? <a class="header-anchor" href="#errortitle" aria-label="Permalink to “errorTitle?”">​</a></h3><blockquote><p><code>optional</code> <strong>errorTitle?</strong>: <code>string</code> | <code>null</code></p></blockquote><p>Normalized form of <code>errorMessage</code>, with ids, numbers, URLs and quoted literals replaced by placeholder tokens, so runs that failed for the same reason share one title you can group on. <code>null</code> when the run did not fail.</p><hr><h3 id="executionstartedat" tabindex="-1">executionStartedAt? <a class="header-anchor" href="#executionstartedat" aria-label="Permalink to “executionStartedAt?”">​</a></h3><blockquote><p><code>optional</code> <strong>executionStartedAt?</strong>: <code>string</code> | <code>null</code></p></blockquote><p>ISO timestamp of the true execution start, stamped once the run actually starts executing. <code>null</code>/absent while the run is still queued. <code>startedAt</code> remains the request time.</p><hr><h3 id="failedsteperrortitle" tabindex="-1">failedStepErrorTitle? <a class="header-anchor" href="#failedsteperrortitle" aria-label="Permalink to “failedStepErrorTitle?”">​</a></h3><blockquote><p><code>optional</code> <strong>failedStepErrorTitle?</strong>: <code>string</code> | <code>null</code></p></blockquote><p>Normalized title of the failed step&#39;s own error, for grouping failures by step-level cause. <code>null</code> whenever <code>failedStepId</code> is <code>null</code>.</p><hr><h3 id="failedstepid" tabindex="-1">failedStepId? <a class="header-anchor" href="#failedstepid" aria-label="Permalink to “failedStepId?”">​</a></h3><blockquote><p><code>optional</code> <strong>failedStepId?</strong>: <code>string</code> | <code>null</code></p></blockquote><p>Id of the step that failed the run — the lowest-index step whose status is <code>&quot;failed&quot;</code>.</p><p>A run started with <code>workflows.start()</code> that aborted during setup, before any of its own steps ran, reads <code>&quot;__setup__&quot;</code> with <code>failedStepKind: &quot;setup&quot;</code> — a synthetic step, so it will not be found in the workflow definition. <code>errorMessage</code> carries the reason (a bad revision, a failed input-schema check, and so on). Only the durable path records that sentinel: the same abort on a <code>syncCallable</code> workflow (<code>workflows.run()</code>) reads <code>null</code> here, with the reason still in <code>errorMessage</code>.</p><p><code>null</code> when the run did not fail, and for the failures that hold no step results at all: a run rejected at launch, a run reclaimed after its executor died, or one whose output failed schema validation after every step completed.</p><hr><h3 id="failedstepkind" tabindex="-1">failedStepKind? <a class="header-anchor" href="#failedstepkind" aria-label="Permalink to “failedStepKind?”">​</a></h3><blockquote><p><code>optional</code> <strong>failedStepKind?</strong>: <code>string</code> | <code>null</code></p></blockquote><p>Kind of the failed step (<code>&quot;database.query&quot;</code>, <code>&quot;llm&quot;</code>, <code>&quot;setup&quot;</code> for the synthetic setup-phase step of a durable run, …). <code>null</code> whenever <code>failedStepId</code> is <code>null</code>.</p><hr><h3 id="instanceid" tabindex="-1">instanceId <a class="header-anchor" href="#instanceid" aria-label="Permalink to “instanceId”">​</a></h3><blockquote><p><strong>instanceId</strong>: <code>string</code></p></blockquote><hr><h3 id="meta" tabindex="-1">meta? <a class="header-anchor" href="#meta" aria-label="Permalink to “meta?”">​</a></h3><blockquote><p><code>optional</code> <strong>meta?</strong>: <code>Record</code>&lt;<code>string</code>, <code>unknown</code>&gt;</p></blockquote><p>User-defined metadata (max 1KB)</p><hr><h3 id="queuedelayms" tabindex="-1">queueDelayMs? <a class="header-anchor" href="#queuedelayms" aria-label="Permalink to “queueDelayMs?”">​</a></h3><blockquote><p><code>optional</code> <strong>queueDelayMs?</strong>: <code>number</code> | <code>null</code></p></blockquote><p>Derived queue delay in ms (<code>executionStartedAt − startedAt</code>), i.e. how long the run sat queued before executing. <code>null</code> while still queued.</p><hr><h3 id="revisionid" tabindex="-1">revisionId <a class="header-anchor" href="#revisionid" aria-label="Permalink to “revisionId”">​</a></h3><blockquote><p><strong>revisionId</strong>: <code>string</code></p></blockquote><hr><h3 id="runid" tabindex="-1">runId <a class="header-anchor" href="#runid" aria-label="Permalink to “runId”">​</a></h3><blockquote><p><strong>runId</strong>: <code>string</code></p></blockquote><hr><h3 id="runkey" tabindex="-1">runKey <a class="header-anchor" href="#runkey" aria-label="Permalink to “runKey”">​</a></h3><blockquote><p><strong>runKey</strong>: <code>string</code></p></blockquote><hr><h3 id="startedat" tabindex="-1">startedAt? <a class="header-anchor" href="#startedat" aria-label="Permalink to “startedAt?”">​</a></h3><blockquote><p><code>optional</code> <strong>startedAt?</strong>: <code>string</code></p></blockquote><p>ISO timestamp stamped when the run started. Emitted by all run serializers (the model field is <code>required</code>); optional here only to tolerate hypothetical legacy records written before the field existed.</p><hr><h3 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to “status”">​</a></h3><blockquote><p><strong>status</strong>: <a href="./../type-aliases/WorkflowRunStatus.html"><code>WorkflowRunStatus</code></a></p></blockquote><hr><h3 id="workflowid" tabindex="-1">workflowId <a class="header-anchor" href="#workflowid" aria-label="Permalink to “workflowId”">​</a></h3><blockquote><p><strong>workflowId</strong>: <code>string</code></p></blockquote><hr><h3 id="workflowkey" tabindex="-1">workflowKey <a class="header-anchor" href="#workflowkey" aria-label="Permalink to “workflowKey”">​</a></h3><blockquote><p><strong>workflowKey</strong>: <code>string</code></p></blockquote>',74)])])}const f=o(d,[["render",l]]);export{p as __pageData,f as default};
